#!/usr/bin/env node
/**
 * bin/venastine.mjs -- the npm entry point (batch 35).
 *
 * npm delivers this project as a FOLDER OF SOURCE, not a binary. This file
 * is the only thing npm can execute, so its whole job is to hand control to
 * the Python that actually implements the harness:
 *
 *   find a Python >= 3.11  ->  make sure its dependencies exist
 *   ->  spawn `python <root>/main.py` with the user's argv, cwd and stdio
 *
 * ZERO npm DEPENDENCIES, deliberately. Node stdlib only. The tarball is
 * first-party source and nothing else, which is what lets
 * THIRD_PARTY_NOTICES.md say the npm channel adds no licence surface. Do not
 * add a dependency here without changing that file too.
 *
 * WHAT THIS FILE MUST NEVER DO, and why each one is a real bug and not a
 * style preference:
 *
 *   * Never set PYTHONPATH. tools/isolation.py builds its child's PYTHONPATH
 *     from the PARENT's resolved sys.path -- "handing the child the paths the
 *     parent actually resolved is deterministic". A value injected here would
 *     be inherited into that computation and poison it.
 *   * Never set AGENT_WORKSPACE. WORKSPACE_DIR is a PERMISSION BOUNDARY, not
 *     a storage location: file_ops auto-approves writes inside it and demands
 *     approval outside. Redirecting it to a shared home directory would
 *     silently auto-approve writes there from every project.
 *   * Never install without consent. See ensureRuntime().
 */

import { spawnSync } from 'node:child_process';
import crypto from 'node:crypto';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import readline from 'node:readline';
import { fileURLToPath } from 'node:url';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.dirname(HERE);
const REQUIREMENTS = path.join(ROOT, 'requirements.txt');
const MAIN = path.join(ROOT, 'main.py');
const CONFIG_FILE = path.join(ROOT, 'config.yaml');
const CONFIG_UPDATE = path.join(ROOT, 'config_update.py');

/**
 * ~/.config/venastine ON EVERY PLATFORM, Windows included.
 *
 * Not %APPDATA%, however Node-idiomatic that would be. The Python half of
 * this directory is already fixed: core/config_loader.py, mcp_client/config.py
 * and core/workspace_trust.py all resolve their user tier with
 * os.path.expanduser("~/.config/venastine"). Splitting one config directory
 * across two locations by platform is the bug this constant exists to avoid.
 */
const CONFIG_HOME = path.join(os.homedir(), '.config', 'venastine');

/**
 * Where config_update.py keeps the pristine copy and the user's mirror.
 *
 * Spelled in two languages, so a docs-consistency test holds this against
 * `config_update.STATE_DIRNAME`. Node owns only the two cheap halves -- the
 * post-session copy below, and the doctor lines -- because everything else
 * needs a YAML parser and this file has ZERO dependencies by design.
 */
const CONFIG_STATE = path.join(CONFIG_HOME, 'config-state');

const MIN_PYTHON = [3, 11];

/** Python floor, in the terms the project already states it in (#144). */
const PYTHON_FLOOR_MESSAGE =
  `Venastine needs Python ${MIN_PYTHON.join('.')} or newer.\n` +
  '\n' +
  'mcp_client/client.py uses asyncio.timeout (3.11+) and 27 sites use runtime\n' +
  '`X | Y` annotations (3.10+). On an older interpreter the harness installs\n' +
  'and then fails from inside the MCP connect path, which is why this refuses\n' +
  'here instead.\n' +
  '\n' +
  'Install Python 3.11+, or point VENASTINE_PYTHON at one:\n' +
  '  VENASTINE_PYTHON=/path/to/python3.12 venastine';

function readPackageVersion() {
  try {
    return JSON.parse(fs.readFileSync(path.join(ROOT, 'package.json'), 'utf8')).version;
  } catch {
    return '0.0.0';
  }
}

/**
 * Candidate interpreters, best first. The loop takes the first that satisfies
 * the floor, so an old `python3` earlier in the list simply falls through to a
 * newer explicit one rather than failing the launch.
 */
function pythonCandidates() {
  if (process.env.VENASTINE_PYTHON) {
    return [{ cmd: process.env.VENASTINE_PYTHON, args: [], explicit: true }];
  }
  if (process.platform === 'win32') {
    // `py -3` is the launcher's newest install; the explicit ones are the
    // fallback for machines without the py launcher on PATH.
    return [
      { cmd: 'py', args: ['-3'] },
      { cmd: 'python', args: [] },
      { cmd: 'python3', args: [] },
      { cmd: 'py', args: ['-3.13'] },
      { cmd: 'py', args: ['-3.12'] },
      { cmd: 'py', args: ['-3.11'] },
    ];
  }
  return [
    { cmd: 'python3', args: [] },
    { cmd: 'python3.13', args: [] },
    { cmd: 'python3.12', args: [] },
    { cmd: 'python3.11', args: [] },
    { cmd: 'python', args: [] },
  ];
}

const PROBE = 'import sys; print("%d.%d" % sys.version_info[:2]); print(sys.executable)';

function probe(candidate) {
  const r = spawnSync(candidate.cmd, [...candidate.args, '-c', PROBE], {
    encoding: 'utf8',
    // Windows resolves `py`/`python` through PATHEXT, which needs the shell
    // off but the extension search on -- spawnSync does that for us. What it
    // does NOT do is survive a missing binary, hence the status check below.
    windowsHide: true,
  });
  if (r.status !== 0 || !r.stdout) return null;
  const [version, executable] = r.stdout.trim().split(/\r?\n/);
  if (!version || !executable) return null;
  const [major, minor] = version.split('.').map(Number);
  return { ...candidate, version, executable, major, minor };
}

function findPython() {
  const rejected = [];
  for (const candidate of pythonCandidates()) {
    const found = probe(candidate);
    if (!found) continue;
    if (found.major > MIN_PYTHON[0] ||
        (found.major === MIN_PYTHON[0] && found.minor >= MIN_PYTHON[1])) {
      return found;
    }
    rejected.push(`${found.executable} (${found.version})`);
  }
  const detail = rejected.length
    ? `\n\nFound, but too old: ${rejected.join(', ')}`
    : '\n\nNo Python interpreter was found on PATH.';
  fail(PYTHON_FLOOR_MESSAGE + detail);
}

function requirementsHash() {
  return crypto.createHash('sha256')
    .update(fs.readFileSync(REQUIREMENTS))
    .digest('hex')
    .slice(0, 12);
}

/**
 * The runtime directory is keyed by VERSION AND requirements hash together.
 *
 * Either alone is not enough: a version bump with unchanged pins should reuse
 * the environment, and an edited pin within one version must NOT. Keying on
 * both means every distinct dependency set gets a clean venv instead of a
 * half-migrated one, and switching back to an older install finds its own
 * environment still intact.
 */
function runtimePaths() {
  const dir = path.join(CONFIG_HOME, 'runtime', `${readPackageVersion()}-${requirementsHash()}`);
  return {
    dir,
    python: process.platform === 'win32'
      ? path.join(dir, 'Scripts', 'python.exe')
      : path.join(dir, 'bin', 'python'),
    // Written LAST, and it -- not the directory -- is what "ready" means. A
    // venv whose pip install died half way exists on disk and would otherwise
    // read as installed, then fail on a missing import at the first model call.
    stamp: path.join(dir, 'venastine-runtime.json'),
  };
}

function isReady(rt) {
  return fs.existsSync(rt.stamp) && fs.existsSync(rt.python);
}

// Non-comment lines in requirements.txt. NOT a count of pins, which is what
// it was called until batch 140: some lines are ranges (a floor and a
// ceiling, like `rich`'s), so the screen that said "N pinned packages" was
// promising something the file does not say. The exact set is in the file
// the screen names, which is what makes the count enough. (This comment
// said "2 of the 18" until batch 208, by when it was 4 of 20: a count in
// prose beside the code that computes it is the copy that drifts.)
function countRequirements() {
  return fs.readFileSync(REQUIREMENTS, 'utf8')
    .split(/\r?\n/)
    .filter((line) => line.trim() && !line.trim().startsWith('#'))
    .length;
}

// ROADMAP_v3 §88 (A83). The harness runs under this process with the console
// inherited, and it is the terminal's one reader from then on, so this
// process stops reading in so many words: rl.close() only ASKS libuv to stop,
// and on Windows its console reader is a thread whose read in flight cannot
// be cancelled. pause() is the same request made of the stream itself, and
// unref() lets nothing about stdin keep this process alive. Measured in a
// console of its own, five keys typed at the child after the consent all
// reached it, before this and after it, three runs each: the old shape
// lost nothing there, and this one loses nothing either.
function ask(question) {
  return new Promise((resolve) => {
    const rl = readline.createInterface({ input: process.stdin, output: process.stdout });
    rl.question(question, (answer) => {
      rl.close();
      process.stdin.pause();
      if (typeof process.stdin.unref === 'function') process.stdin.unref();
      resolve(/^y(es)?$/i.test(answer.trim()));
    });
  });
}

/**
 * Build the Python environment, only ever with the user's say-so.
 *
 * The consent prompt is not ceremony. This is the one action the launcher
 * takes on its own initiative -- it runs a network install of everything in
 * requirements.txt -- and the project's own rule for that case is D17/D31:
 *
 * NO COUNT IN THIS SENTENCE, deliberately (batch 140). It said "17
 * pinned distributions" and the file had 22 installable lines when that was
 * measured, 18 now that batch 136 moved the test packages out. The screen
 * below prints the live number; prose that restates a computed value is a
 * second copy of it, and this is the copy that drifted.
 * show what will run and confirm it. That is also why the bootstrap is here
 * and not in an npm `postinstall` hook, where it would run unannounced and be
 * skipped entirely under `--ignore-scripts`.
 *
 * NOT A TTY AND NO --venastine-yes => REFUSE AND PRINT THE COMMAND. A CI job
 * or a piped invocation must not be able to trigger an unattended install
 * just by being unable to answer.
 */
async function ensureRuntime(python, rt, { assumeYes }) {
  if (isReady(rt)) return;

  const uv = findUv();
  const summary =
    'Venastine needs a Python environment (first run).\n' +
    `  python  : ${python.version}  (${python.executable})\n` +
    `  venv    : ${rt.dir}\n` +
    `  install : ${countRequirements()} packages from requirements.txt` +
    `${uv ? ', with uv' : ''}\n`;

  if (!assumeYes) {
    if (!process.stdin.isTTY) {
      fail(
        summary +
        '\nRefusing to install unattended (no terminal to ask in).\n' +
        'Re-run interactively, pass --venastine-yes, or build it yourself:\n' +
        `  ${python.executable} -m venv "${rt.dir}"\n` +
        `  "${rt.python}" -m pip install -r "${REQUIREMENTS}"`
      );
    }
    process.stdout.write(summary);
    const ok = await ask('Proceed? [y/N] ');
    if (!ok) fail('Cancelled. Nothing was installed.');
  } else {
    process.stdout.write(summary);
  }

  let installer;
  try {
    installer = installRequirements(python, rt, uv);
  } catch (e) {
    // Leave nothing half-built behind: the next run must start clean rather
    // than inherit a venv that is missing an unknown subset of its packages.
    fs.rmSync(rt.dir, { recursive: true, force: true });
    fail(`Environment setup failed: ${e.message}`);
  }

  fs.writeFileSync(rt.stamp, JSON.stringify({
    version: readPackageVersion(),
    requirementsHash: requirementsHash(),
    python: python.executable,
    pythonVersion: python.version,
    installer,
    createdAt: new Date().toISOString(),
  }, null, 2));
}

/**
 * uv, when it is on PATH and VENASTINE_NO_UV is unset (ROADMAP_v3 §93), the
 * same rule scripts/install.py keeps for the GitHub installers.
 */
function findUv() {
  const off = process.env.VENASTINE_NO_UV;
  if (off && off !== '0') return null;
  const r = spawnSync('uv', ['--version'], { encoding: 'utf8', windowsHide: true });
  return r.status === 0 ? 'uv' : null;
}

/**
 * COPY, NEVER uv's DEFAULT LINK. On Linux and Windows uv hardlinks each file
 * out of its cache, which would make the venv's code one inode with a file
 * under ~/.cache/uv -- writable where ~/.config/venastine is protected.
 * Bytecode is compiled as pip compiles it, so a first launch compiles nothing.
 */
const UV_INSTALL = ['pip', 'install', '--link-mode', 'copy', '--compile-bytecode'];

/**
 * The venv, then requirements.txt in it: by uv when there is one, by pip
 * otherwise. `python -m venv` either way, so the venv holds pip as it always
 * has. A uv that fails -- too old, or blind to a mirror only pip.conf names
 * -- costs a fresh venv and a pip install, never the launch. uv runs from
 * the venv's directory so a project's uv settings in cwd are not read.
 */
function installRequirements(python, rt, uv) {
  run(python.executable, ['-m', 'venv', rt.dir]);
  if (uv) {
    try {
      run(uv, [...UV_INSTALL, '--python', rt.python, '-r', REQUIREMENTS], { cwd: rt.dir });
      return 'uv';
    } catch (e) {
      process.stdout.write(`uv could not install them (${e.message}); starting again with pip.\n`);
      fs.rmSync(rt.dir, { recursive: true, force: true });
      run(python.executable, ['-m', 'venv', rt.dir]);
    }
  }
  run(rt.python, ['-m', 'pip', 'install', '--disable-pip-version-check',
                  '-r', REQUIREMENTS]);
  return 'pip';
}

function run(cmd, args, options = {}) {
  const r = spawnSync(cmd, args, { stdio: 'inherit', windowsHide: true, ...options });
  if (r.error) throw r.error;
  if (r.status !== 0) throw new Error(`${path.basename(cmd)} ${args[0]} exited ${r.status}`);
}

/**
 * Put the user's own settings back into config.yaml after npm replaced it.
 *
 * npm replaces a package directory WHOLESALE on update -- measured with
 * `npm pack` and two installs into a scratch prefix: an edited
 * `max_tokens: 31337` came back as the shipped `16000`. `config.yaml` ships
 * inside the package (CONFIG_ARCHITECTURE.md locks it to one location for a
 * security reason that this problem does not touch), so without this the
 * update silently discards every value the user set.
 *
 * `config_update.py` owns every decision; this call owns none of them. It
 * runs on every launch and does nothing on almost all of them -- the module
 * imports no first-party code until it has decided there is a merge to do,
 * because `import config_schema` alone costs 294ms of pydantic and ruamel.
 *
 * THE STATUS IS DELIBERATELY UNCHECKED. A configuration-history feature must
 * not be able to stop the harness from starting; the module says so itself by
 * always exiting 0, and this is the other half of that promise.
 *
 * `firstRun` is the one fact Python cannot work out for itself: it is read
 * from the venv stamp BEFORE ensureRuntime() builds it. Without it, an
 * install that was already in use when this feature arrived would have its
 * edited config.yaml recorded as the pristine baseline, and those edits would
 * be lost at the next update instead of preserved by it.
 */
function syncConfig(rt, firstRun) {
  try {
    spawnSync(rt.python, [CONFIG_UPDATE, ...(firstRun ? ['--first-run'] : [])], {
      stdio: 'inherit',
      cwd: ROOT,
      windowsHide: true,
    });
  } catch {
    // See above: never fatal.
  }
}

/**
 * Mirror config.yaml AFTER the session, so a /config write survives an update.
 *
 * This is the common upgrade order and the whole feature misses its own case
 * without it: change a setting, exit, `npm update` days later, launch. By
 * then npm has replaced the file, so the only copy of that change is the one
 * taken here. The next launch's mirror is too late.
 *
 * THIS USED TO BE FOUR LINES OF fs.copyFileSync HERE, and they were the one
 * writer not subject to the module's rule 1 ("the mirror is refreshed only
 * when the version still matches"). They copied whenever a `version` file
 * existed -- so a merge that FAILED, which deliberately leaves the version
 * and the mirror untouched so the next launch can retry, was followed at
 * session end by the newly shipped config.yaml being copied over the mirror.
 * The user's settings were then gone from every copy, permanently, and the
 * retry found nothing to restore. The state directory is also global while
 * this file's ROOT is not, so a checkout run overwrote an npm install's
 * mirror with the checkout's own config.yaml.
 *
 * So the decision lives in Python, where it is tested, and this spawns it.
 * An interpreter start at session EXIT costs nothing anybody is waiting for.
 */
function mirrorConfig(rt) {
  try {
    spawnSync(rt.python, [CONFIG_UPDATE, '--mirror'], {
      stdio: 'inherit',
      cwd: ROOT,
      windowsHide: true,
    });
  } catch {
    // Never fatal, for syncConfig's reason.
  }
}

/** Walks up from cwd the way dotenv's find_dotenv(usecwd=True) now does. */
function findEnvFile() {
  let dir = process.cwd();
  for (;;) {
    const candidate = path.join(dir, '.env');
    if (fs.existsSync(candidate)) return candidate;
    const parent = path.dirname(dir);
    if (parent === dir) return null;
    dir = parent;
  }
}

/**
 * The child's environment: inherit everything, then fill in ONLY what is
 * missing. Every branch here defers to a value the user already set.
 */
function childEnv() {
  const env = { ...process.env };
  const cwd = process.cwd();

  // Credentials. cwd wins, because per-project keys are a real workflow; the
  // user-level file is the fallback that makes a globally-installed CLI
  // usable from directories that have no providers.json of their own.
  if (!env.AGENT_PROVIDERS_FILE && !fs.existsSync(path.join(cwd, 'providers.json'))) {
    const shared = path.join(CONFIG_HOME, 'providers.json');
    if (fs.existsSync(shared)) env.AGENT_PROVIDERS_FILE = shared;
  }

  // State. ONE decision drives BOTH variables -- a global database writing to
  // a local log is worse than either arrangement on its own.
  //
  // Why global at all: main.py sets project_path = os.getcwd(), and UserMemory
  // carries `scope` AND `project_path` (M12/D25) precisely so ONE database can
  // tell projects apart. Per-directory databases would put an accidental
  // scoping axis on top of that deliberate one -- `--thread <uuid>` would stop
  // resolving outside the directory it was created in, and a memory saved
  // scope="global" would be global only inside one folder.
  //
  // An existing ./app.db always wins, so running this launcher inside a
  // checkout keeps using the data already there instead of orphaning it.
  if (!env.APP_DB_PATH && !fs.existsSync(path.join(cwd, 'app.db'))) {
    env.APP_DB_PATH = path.join(CONFIG_HOME, 'app.db');
    if (!env.AGENT_LOG_FILE) env.AGENT_LOG_FILE = path.join(CONFIG_HOME, 'logs', 'app.log');
  }

  // AGENT_OUTPUT_DIR is deliberately untouched: research artifacts belong
  // beside the work that prompted them, and nothing reads them back -- the
  // report and claims live in the PipelineRunRecord row, not in output/.
  return env;
}

/**
 * One line about the config merge, WITHOUT starting Python.
 *
 * --venastine-doctor returns before ensureRuntime(), so there may be no
 * interpreter to ask. Everything here is a plain text file for that reason.
 */
function configStateSummary() {
  try {
    // installs.json maps an install directory to its state subdirectory.
    // READ, never recomputed: config_update.py owns that naming, and two
    // languages agreeing about a hash by inspection would fail silently --
    // the mirror would be written where the merge does not look.
    const installs = JSON.parse(
      fs.readFileSync(path.join(CONFIG_STATE, 'installs.json'), 'utf8'));
    const dir = path.join(CONFIG_STATE, installs[fs.realpathSync(ROOT)]);
    const version = fs.readFileSync(path.join(dir, 'version'), 'utf8').trim();
    const record = path.join(dir, 'last-update.txt');
    const last = fs.existsSync(record)
      ? `, last merged ${fs.statSync(record).mtime.toISOString().slice(0, 10)}`
      : '';
    return `${dir} (tracking ${version}${last})`;
  } catch {
    return `${CONFIG_STATE} (not tracked yet; the next launch starts it)`;
  }
}

/** A stamp from before ROADMAP_v3 §93 names no installer, and was pip's. */
function installedBy(rt) {
  if (!isReady(rt)) return `${findUv() ? 'uv' : 'pip'} (on the first run)`;
  try {
    return JSON.parse(fs.readFileSync(rt.stamp, 'utf8')).installer || 'pip';
  } catch {
    return 'pip';
  }
}

function doctor(python, rt) {
  const cwd = process.cwd();
  const env = childEnv();
  const localProviders = path.join(cwd, 'providers.json');
  const lines = [
    `venastine ${readPackageVersion()}`,
    `  package root  : ${ROOT}`,
    `  node          : ${process.version}`,
    `  python        : ${python.version}  (${python.executable})`,
    `  venv          : ${rt.dir}`,
    `  venv ready    : ${isReady(rt) ? 'yes' : 'no (first run will build it)'}`,
    `  installed by  : ${installedBy(rt)}`,
    `  cwd           : ${cwd}`,
    `  providers.json: ${env.AGENT_PROVIDERS_FILE
        || (fs.existsSync(localProviders) ? localProviders : '(none found)')}`,
    `  .env          : ${env.AGENT_ENV_FILE || findEnvFile() || '(none found)'}`,
    `  app.db        : ${env.APP_DB_PATH || path.join(cwd, 'app.db')}`,
    `  log file      : ${env.AGENT_LOG_FILE || path.join(cwd, 'logs', 'app.log')}`,
    `  output dir    : ${env.AGENT_OUTPUT_DIR || path.join(cwd, 'output')}`,
    `  workspace     : ${env.AGENT_WORKSPACE || path.join(cwd, 'workspace')}`,
    `  config.yaml   : ${CONFIG_FILE}`,
    `  config state  : ${configStateSummary()}`,
  ];
  process.stdout.write(lines.join('\n') + '\n');
}

function fail(message) {
  process.stderr.write(message.replace(/\n?$/, '\n'));
  process.exit(1);
}

async function main() {
  const argv = process.argv.slice(2);

  // Launcher-owned flags are PREFIXED because main.py takes a positional
  // `query`: a bare `venastine doctor` would be sent to the model as a
  // research question rather than reaching this file.
  const assumeYes = argv.includes('--venastine-yes');
  const wantDoctor = argv.includes('--venastine-doctor');
  const wantReinstall = argv.includes('--venastine-reinstall');
  const passthrough = argv.filter((a) => !a.startsWith('--venastine-'));

  const python = findPython();
  const rt = runtimePaths();

  // BEFORE ensureRuntime, which is what makes it an answer: "has this install
  // ever been launched?" is the only way to know whether the config.yaml in
  // front of us is pristine or already edited. See syncConfig().
  const firstRun = !isReady(rt);

  if (wantReinstall) {
    // The venv only. The config state in CONFIG_STATE is the user's own
    // settings history and has nothing to do with a broken environment --
    // removing it here would throw away the edits an update is about to need.
    fs.rmSync(rt.dir, { recursive: true, force: true });
    process.stdout.write(`Removed ${rt.dir}\n`);
  }

  if (wantDoctor) {
    doctor(python, rt);
    return;
  }

  await ensureRuntime(python, rt, { assumeYes });
  syncConfig(rt, firstRun);

  // Let the child own the terminal's interrupt. Without this, Ctrl+C kills
  // the launcher first and the harness loses its chance to shut down.
  process.on('SIGINT', () => {});

  // main.py BY PATH, so its directory becomes sys.path[0]: the harness relies
  // on the project root being importable (AGENTS.md, "the project root is on
  // sys.path"). stdio:'inherit' is what gives the Textual TUI a real terminal.
  const child = spawnSync(rt.python, [MAIN, ...passthrough], {
    stdio: 'inherit',
    cwd: process.cwd(),
    env: childEnv(),
    windowsHide: false,
  });

  mirrorConfig(rt);

  if (child.error) fail(`Could not start the harness: ${child.error.message}`);
  if (child.signal) process.exit(128 + (os.constants.signals[child.signal] || 0));
  process.exit(child.status ?? 1);
}

main().catch((e) => fail(e.stack || String(e)));

# Pass 6b — Re-validate

You will receive the revised claims from Pass 6a — ONLY the claims it was just given, not the full original claim set. Most were rewritten; a claim it was asked only to check may come back with its text unchanged, and it is re-validated all the same.

Re-run the same checks Pass 3a (source grounding) and Pass 3b (critic) performed, but scoped to just this revised subset:

1. **Grounding**: for each revised claim, re-derive a search query from its (now possibly different) entity/subject and check it against available sources, the same way Pass 3a did — deduplicate entities across this batch first, search once per unique entity, map back to claims. Assign a fresh `grounded`/`partial`/`ungrounded` status based on the REVISED text, not the original.
2. **Critic**: re-check the revised claims for fallacies and contradictions, the same way Pass 3b did, including against the rest of the (unrevised) claim set if relevant context is available to you.

Respond with ONLY this JSON structure:

```json
{
  "grounding": [
    {"claim_id": "c001", "sources": [{"url": "...", "quote": "...", "similarity_score": 0.0, "authority_adjustment": 0.0, "authority_reason": "..."}], "status": "grounded"}
  ],
  "critic": [
    {"claim_id": "c001", "fallacies": ["..."], "contradictions": ["..."], "severity": 0.0}
  ]
}
```

